/**
 * 自检页「说明」那一行的渲染辅助：给长路径留出折行点（纯函数，只做这一件事）。
 *
 * 为什么需要：那些说明里常有两条长路径（node 的入口 + dsh 的 bin.js），它们是一整串没有空格的
 * 字符。浏览器认的断点是空格 / 连字符这类，于是折行只能从路径**中间**切 —— 实测会断成
 * `…/@deepseek-` + `ai/dsh/lib/bin.js`，第二行只剩一小截、看着像排版坏了。渲染成「一段一个
 * 分隔符结尾的片段 + 片段之间一个 `<wbr>`」之后，断点就落在路径分隔符上。
 *
 * **只切分、不产生 HTML**：说明文字里有用户机器上的真实路径，渲染层把它当标记解析就是一条注入
 * 面（`v-html` 那条路在本页被自检钉着不许走）。`<wbr>` 是元素、不是字符，所以复制出来的文本
 * 与原来一字不差（自检里有往返断言）。
 *
 * 分隔符认两种：`/`（POSIX）与 `\`（Windows）—— dsh 的 Windows 用户看到的就是后者。
 */
export function detailSegments(text: string): string[] {
  // lookbehind：在分隔符**之后**断开，分隔符本身留在前一段末尾
  return String(text ?? '').split(/(?<=[/\\])/);
}
